    return { ok: false, error: 'Никнейм должен быть строкой.' };
  }
  let val = raw.trim().replace(/\s+/g, ' ');
  if (val.length < NICKNAME_MIN || val.length > NICKNAME_MAX) {
    return { ok: false, error: `Никнейм от ${NICKNAME_MIN} до ${NICKNAME_MAX} символов.` };
  }
  // запрещаем управляющие символы
  if (/[\x00-\x1F\x7F]/.test(val)) {
    return { ok: false, error: 'Никнейм содержит недопустимые символы.' };
  }
  return { ok: true, value: val };
