const DB_NAME = 'flappyBirdDB';
const STORE_NAME = 'scores';
const DB_VERSION = 1;

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        store.createIndex('gameId_score', ['gameId', 'score'], { unique: false });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

/**
 * LocalStorage-реализация IReadableLeaderboard / IWritableLeaderboard
 */
export function createLocalLeaderboard() {
  /** @type {import('../../domain/contracts.js').IReadableLeaderboard} */
  const readable = {
    async getScores(gameId, topN = 10) {
      const db = await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const index = store.index('gameId_score');
        const range = IDBKeyRange.bound([gameId, 0], [gameId, Infinity]);
        const req = index.openCursor(range, 'prev');
        const results = [];
        req.onsuccess = () => {
          const cursor = req.result;
          if (cursor && results.length < topN) {
            results.push({
              nickname: cursor.value.nickname,
              score: cursor.value.score,
              gameId: cursor.value.gameId,
              playedAt: cursor.value.playedAt,
            });
            cursor.continue();
          } else {
            resolve(results);
          }
        };
        req.onerror = () => reject(req.error);
      });
    },

    async getBestScore(gameId) {
      const db = await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const index = store.index('gameId_score');
        const range = IDBKeyRange.bound([gameId, 0], [gameId, Infinity]);
        const req = index.openCursor(range, 'prev');
        req.onsuccess = () => {
          const cursor = req.result;
          resolve(cursor ? cursor.value.score : null);
        };
        req.onerror = () => reject(req.error);
      });
    },
  };

  /** @type {import('../../domain/contracts.js').IWritableLeaderboard} */
