 * @file Firebase Firestore leaderboard (модульный, инициализируется через CDN)
 */

// Предполагается, что firebase загружен через CDN в window.firebase
function getFirestore() {
  if (typeof window === 'undefined' || !window.firebase) {
    throw new Error('Firebase SDK не загружен. Подключите CDN в index.html');
  }
  return window.firebase.firestore;
}

/**
 * @param {object} config — { projectId, apiKey, authDomain, appName? }
 * @returns {{ readable: IReadableLeaderboard, writable: IWritableLeaderboard }}
 */
export function createFirebaseLeaderboard(config) {
  const { projectId, apiKey, authDomain } = config;
  const appName = config.appName || 'flappy-bird';

  function getApp() {
    const firebase = window.firebase;
    const apps = firebase.apps;
    let app = apps.find((a) => a.name === appName);
    if (!app) {
      app = firebase.initializeApp({
        apiKey,
        authDomain,
        projectId,
      }, appName);
    }
    return app;
  }

  function getDB() {
    // __firestore_instance закешируем после первого создания
    if (!getDB._instance) {
      getDB._instance = getFirestore()(getApp());
    }
    return getDB._instance;
  }

  function scoresCollection(gameId) {
    const db = getDB();
    return db.collection('scores')
      .where('gameId', '==', gameId)
      .orderBy('score', 'desc');
  }

  /** @type {import('../../domain/contracts.js').IReadableLeaderboard} */
  const readable = {
    async getScores(gameId, topN = 10) {
      if (!gameId) return [];
      const snapshot = await scoresCollection(gameId).limit(topN).get();
      return snapshot.docs.map((d) => d.data());
    },
    async getBestScore(gameId) {
      if (!gameId) return null;
      const snapshot = await scoresCollection(gameId).limit(1).get();
      if (snapshot.empty) return null;
      return snapshot.docs[0].data().score;
    },
  };

  /** @type {import('../../domain/contracts.js').IWritableLeaderboard} */
  const writable = {
    async saveScore(entry) {
      const db = getDB();
      await db.collection('scores').add(entry);
    },
  };

  return { readable, writable };
}", "path": "src/infrastructure/FirebaseLeaderboard.js"}

