 * @file Flappy Bird — реализация IGame для использования через интерфейс
 */

/**
 * @param {HTMLCanvasElement} canvas
 * @returns {import('../../domain/contracts.js').IGame}
 */
export function createFlappyBird(canvas) {
  const ctx = canvas.getContext('2d');

  // ---- constants ----
  const W = canvas.width;
  const H = canvas.height;
  const GRAVITY = 0.45;
  const JUMP = -7;
  const PIPE_W = 50;
  const GAP = 140;
  const PIPE_SPEED = 2.8;

  // ---- state ----
  let bird = { x: 60, y: H / 2, vy: 0, r: 12 };
  let pipes = [];
  let score = 0;
  let frameId = null;
  let running = false;
  let paused = false;
  let gameOverCallbacks = [];

  let frameCount = 0;

  function reset() {
    bird = { x: 60, y: H / 2, vy: 0, r: 12 };
    pipes = [];
    score = 0;
    frameCount = 0;
  }

  function onKeyDown(e) {
    if (!running || paused) return;
    if (e.code === 'Space' || e.key === ' ') {
      e.preventDefault();
      bird.vy = JUMP;
    }
  }

  // ---- game loop ----
  function loop() {
    if (!running || paused) return;

    frameCount++;

    // Add pipes
    if (frameCount % 90 === 0) {
      const topH = 40 + Math.random() * (H - GAP - 80);
      pipes.push({ x: W, topH, bottomY: topH + GAP, scored: false });
    }

    // Physics
    bird.vy += GRAVITY;
    bird.y += bird.vy;

    // Pipes
    for (let i = pipes.length - 1; i >= 0; i--) {
      const p = pipes[i];
      p.x -= PIPE_SPEED;

      if (!p.scored && p.x + PIPE_W < bird.x) {
        p.scored = true;
        score++;
      }

      if (p.x + PIPE_W < 0) {
        pipes.splice(i, 1);
      }
    }

    // Collisions
    let dead = false;
    if (bird.y + bird.r > H || bird.y - bird.r < 0) dead = true;
    for (const p of pipes) {
      if (
        bird.x + bird.r > p.x &&
        bird.x - bird.r < p.x + PIPE_W &&
        (bird.y - bird.r < p.topH || bird.y + bird.r > p.bottomY)
      ) {
        dead = true;
        break;
      }
    }

    if (dead) {
      running = false;
      gameOverCallbacks.forEach((cb) => cb({ score, gameId: 'flappy-bird' }));
      draw();
      return;
    }

    draw();
    frameId = requestAnimationFrame(loop);
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Sky
    ctx.fillStyle = '#70c5ce';
    ctx.fillRect(0, 0, W, H);

    // Pipes
    ctx.fillStyle = '#228b22';
    for (const p of pipes) {
      ctx.fillRect(p.x, 0, PIPE_W, p.topH);
      ctx.fillRect(p.x, p.bottomY, PIPE_W, H - p.bottomY);
    }

    // Bird
    ctx.fillStyle = '#f5c842';
    ctx.beginPath();
    ctx.arc(bird.x, bird.y, bird.r, 0, Math.PI * 2);
    ctx.fill();

    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '24px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`Score: ${score}`, 10, 30);
  }

  // ---- public API (IGame) ----

  function mount(canvasEl, input, loop) {
    // input и loop — заглушки совместимости; слушаем клавиатуру напрямую
    window.addEventListener('keydown', onKeyDown);
  }

  function start() {
    reset();
    running = true;
    paused = false;
    if (frameId) cancelAnimationFrame(frameId);
    loop();
  }

  function pause() {
    paused = true;
  }

  function resume() {
    if (running) {
      paused = false;
      loop();
    }
  }

  function dispose() {
    running = false;
    if (frameId) cancelAnimationFrame(frameId);
    window.removeEventListener('keydown', onKeyDown);
    gameOverCallbacks = [];
  }

  function onGameOver(cb) {
    gameOverCallbacks.push(cb);
  }

  return { mount, start, pause, resume, dispose, onGameOver };
}", "path": "src/games/FlappyBird.js"}

