    ctx.fillStyle = '#70c5ce';
    ctx.fillRect(0, 0, W, H);

    // Pipes
    ctx.fillStyle = '#228b22';
    for (const p of pipes) {
      ctx.fillRect(p.x, 0, PIPE_W, p.topH);
      ctx.fillRect(p.x, p.bottomY, PIPE_W, H - p.bottomY);
    }

    // Bird
    ctx.fillStyle = '#f5c842';
    ctx.beginPath();
    ctx.arc(bird.x, bird.y, bird.r, 0, Math.PI * 2);
    ctx.fill();

    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '24px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`Score: ${score}`, 10, 30);
  }

  // ---- public API (IGame) ----

  function mount(canvasEl, input, loop) {
    // input и loop — заглушки совместимости; слушаем клавиатуру напрямую
    window.addEventListener('keydown', onKeyDown);
  }

  function start() {
    reset();
    running = true;
    paused = false;
    if (frameId) cancelAnimationFrame(frameId);
    loop();
  }

  function pause() {
    paused = true;
  }

  function resume() {
    if (running) {
      paused = false;
      loop();
    }
  }

  function dispose() {
    running = false;
    if (frameId) cancelAnimationFrame(frameId);
    window.removeEventListener('keydown', onKeyDown);
    gameOverCallbacks = [];
  }

  function onGameOver(cb) {
    gameOverCallbacks.push(cb);
  }

  return { mount, start, pause, resume, dispose, onGameOver };
}

