<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Flappy Bird — DDD Architecture</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: system-ui, -apple-system, sans-serif;
      background: #2d2d2d;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      margin: 0;
    }
    .game-wrapper {
      background: #1a1a1a;
      padding: 20px;
      border-radius: 12px;
      box-shadow: 0 8px 32px rgba(0,0,0,0.5);
    }
    .game-area {
      position: relative;
    }
    canvas {
      display: block;
      background: #70c5ce;
      border-radius: 8px;
      width: 400px;
      height: 500px;
    }
    .overlay {
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(0,0,0,0.7);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      border-radius: 8px;
      color: white;
      gap: 12px;
    }
    .hidden { display: none !important; }

    #nickname-screen { z-index: 10; }
    #gameover-screen { z-index: 20; }

    .overlay input {
      padding: 10px 16px;
      border: none;
      border-radius: 6px;
      font-size: 16px;
      text-align: center;
      width: 200px;
    }
    .overlay button {
      padding: 10px 24px;
      border: none;
      border-radius: 6px;
      background: #f5c842;
      color: #1a1a1a;
      font-weight: bold;
      font-size: 16px;
      cursor: pointer;
      transition: background 0.2s;
    }
    .overlay button:hover { background: #e0b535; }
    .overlay button:disabled { opacity: 0.5; cursor: not-allowed; }

    #leaderboard-container {
      background: rgba(255,255,255,0.9);
      color: #1a1a1a;
      padding: 12px 20px;
      border-radius: 8px;
      min-width: 200px;
      max-height: 200px;
      overflow-y: auto;
      text-align: center;
    }
    #leaderboard-container h3 { margin-bottom: 6px; }
    #leaderboard-container ol { text-align: left; padding-left: 24px; }
    #leaderboard-container li { margin: 2px 0; }

    .game-info {
      margin-top: 12px;
      color: #aaa;
      font-size: 12px;
      text-align: center;
    }
  </style>
</head>
<body>
  <div class="game-wrapper">
    <div class="game-area">
      <canvas id="game-canvas" width="400" height="500"></canvas>

      <!-- Nickname Screen -->
      <div id="nickname-screen" class="overlay">
        <h2>🐦 Flappy Bird</h2>
        <p style="color:#ccc;font-size:14px;">Введите никнейм для таблицы лидеров</p>
        <input id="nickname-input" type="text" maxlength="16" placeholder="Ваш никнейм" />
        <button id="nickname-btn">Play!</button>
      </div>

